-- Execute no Supabase SQL Editor apenas se ainda não executou o schema anterior.
-- O schema existente é compatível com esta versão.
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,credit_limit numeric(12,2) not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null check(type in('income','expense')),description text not null,amount numeric(12,2) not null check(amount>0),date date not null,category text not null default 'Outros',payment_method text not null default 'pix' check(payment_method in('pix','credit_card')),installments integer not null default 1 check(installments between 1 and 6),note text default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.transactions enable row level security;
